export const getSetPriceHistoryUrl = () => {
  return `/backend/api/price-history/set`;
};

/**
 * Deliberately public: writes a shared price-history cache entry keyed by coin/timeFrame, not anything scoped to the caller. No session read today; stays public.
 */
export const setPriceHistory = async (
  setPriceHistoryRequestDto: SetPriceHistoryRequestDto,
  options?: Parameters<typeof httpClient>[1],
): Promise<SetPriceHistoryResponseDto> => {
  const getHeaders = (
    h?: NonNullable<RequestInit['headers']>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Array.isArray(h)) return Object.fromEntries(h);
    return h;
  };
  return httpClient<SetPriceHistoryResponseDto>(getSetPriceHistoryUrl(), {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(setPriceHistoryRequestDto),
  });
};

export const getSetPriceHistoryMutationOptions = <
  TError = SetPriceHistory400,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof setPriceHistory>>,
    TError,
    SetPriceHistoryMutationVariables,
    TContext
  >;
  request?: SecondParameter<typeof httpClient>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof setPriceHistory>>,
  TError,
  SetPriceHistoryMutationVariables,
  TContext
> => {
  const mutationKey = ['setPriceHistory'];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof setPriceHistory>>,
    SetPriceHistoryMutationVariables
  > = (props) => {
    const { data } = props ?? {};

    return setPriceHistory(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

