export const getMetricsUrl = () => {
  return `/backend/api/metrics`;
};

/**
 * Authenticated via a static bearer-token check (Authorization: Bearer {METRICS_SECRET}), not a session - this is a machine-to-machine scrape credential, never a user-facing route, so it is documented with its own bearer security scheme rather than @ApiCookieAuth().
 */
export const metrics = async (options?: Parameters<typeof httpClient>[1]): Promise<string> => {
  return httpClient<string>(getMetricsUrl(), {
    ...options,
    method: 'GET',
  });
};

